-- Target MySQL 8.0+. Runtime menggunakan adapter mysql2/promise.
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('CUSTOMER','ADMIN','DRIVER') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at BIGINT NOT NULL,revoked_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_sessions_user(user_id));
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,description VARCHAR(500) NOT NULL DEFAULT '',price BIGINT UNSIGNED NOT NULL,image_url VARCHAR(1000) NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),INDEX idx_product_category(category_id,active));
CREATE TABLE addresses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(60) NOT NULL,detail VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,address_id BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','CONFIRMED','PREPARING','READY','ASSIGNED','PICKED_UP','ON_DELIVERY','DELIVERED','CANCELLED') NOT NULL DEFAULT 'PENDING',total BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(address_id) REFERENCES addresses(id),INDEX idx_order_customer(customer_id,created_at),INDEX idx_order_status(status,created_at));
CREATE TABLE order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,price BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE deliveries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,driver_id BIGINT UNSIGNED NOT NULL,accepted_at TIMESTAMP NULL,delivered_at TIMESTAMP NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(driver_id) REFERENCES users(id),INDEX idx_driver(driver_id));
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,method ENUM('CASH','BANK_TRANSFER') NOT NULL,status ENUM('UNPAID','PENDING','PAID','FAILED','CANCELLED','REFUNDED') NOT NULL DEFAULT 'UNPAID',verified_by BIGINT UNSIGNED NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(verified_by) REFERENCES users(id));
CREATE TABLE loyalty_accounts(user_id BIGINT UNSIGNED PRIMARY KEY,balance BIGINT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE loyalty_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED UNIQUE,kind ENUM('EARN','REDEEM') NOT NULL,amount BIGINT NOT NULL,balance_after BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE order_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,previous_status VARCHAR(30),next_status VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,message VARCHAR(500) NOT NULL,read_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE settings(`key` VARCHAR(100) PRIMARY KEY,value TEXT NOT NULL);
